import React, { useContext, useState } from "react";
import { CartContext } from "../context/cartContext";
import { graphql, Link } from "gatsby";
import Layout from "../components/layout";
import { UserProfile } from "../interfaces";
import data from "../data/data.json";
import { useTranslation } from "gatsby-plugin-react-i18next";
import { FiArrowLeft } from "react-icons/fi";
import { db } from "../../firebaseConfig";
import { collection, addDoc } from "firebase/firestore";
import emailjs from "emailjs-com";
import PayPalButton from "../components/paypalButton";

const CheckoutPage = () => {
  const { t } = useTranslation();
  const cartContext = useContext(CartContext);
  const [customerEmail, setCustomerEmail] = useState("");
  const [customerName, setCustomerName] = useState("");

  if (!cartContext) {
    return <div>{t("cart.cartContextError")}</div>;
  }

  const userData: UserProfile = data;
  const { cart } = cartContext;
  const total = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);

  interface Order {
    customerName: string;
    customerEmail: string;
    items: typeof cart;
    total: number;
    date: string;
  }

  const formattedOrderDetails = cart
    .map(
      (item) =>
        `${item.name} | Cantidad: ${item.quantity} | Precio: ${(
          item.price * item.quantity
        ).toFixed(2)} CAD`
    )
    .join("\n");

  async function handleTransactionComplete(
    orderDetails: string,
    totalAmount: string,
    customerName: string,
    customerEmail: string
  ): Promise<void> {
    console.log("customerName", customerName);
    console.log("customerEmail", customerEmail);
    console.log("orderDetails", orderDetails);
    if (!customerEmail || !customerName) {
      alert("Por favor, completa los campos de nombre y correo electrónico.");
      return;
    }

    // Guardar pedido en Firestore
    try {
      const order: Order = {
        customerName,
        customerEmail,
        items: cart,
        total: parseFloat(totalAmount),
        date: new Date().toISOString(),
      };
      const orderRef = await addDoc(collection(db, "orders"), order);
      console.log("Pedido guardado con ID:", orderRef.id);
    } catch (error) {
      console.error("Error guardando el pedido:", error);
    }

    // Enviar correo con EmailJS
    try {
      const templateParams = {
        to_name: "Service Client Succulente Sculpture",
        from_name: customerName,
        reply_to: customerEmail,
        phone: "", // Opcional
        order_details: orderDetails,
        total_amount: totalAmount,
      };

      const serviceID = "service_3b7eaqj"; // Reemplaza con tu service ID de EmailJS
      const templateID = "template_jyqdnxg"; // Reemplaza con tu template ID de EmailJS
      const userID = "u2Op-9wm_t5yR4it5"; // Reemplaza con tu user ID de EmailJS

      const response = await emailjs.send(
        serviceID,
        templateID,
        templateParams,
        userID
      );
      console.log("Correo enviado con éxito:", response.status, response.text);
    } catch (error) {
      console.error("Error enviando correo:", error);
    }
  }

  return (
    <Layout data={userData}>
      <div className="container mx-auto p-4 relative mt-4">
        <div className="flex justify-between items-center mb-4">
          <h1 className="text-secondary text-3xl">{t("cart.checkout")}</h1>
          <Link
            to="/cart"
            className="bg-secondary text-light px-4 py-2 rounded flex items-center text-2xl"
          >
            <FiArrowLeft className="text-2xl mr-4" /> {t("cart.backToCart")}
          </Link>
        </div>

        <div className="bg-primary text-secondary p-6 rounded-lg shadow-md">
          <h2 className="text-2xl font-bold mb-4">
            {t("cart.purchaseSummary")}
          </h2>
          <div className="space-y-2">
            {cart.map((item) => (
              <div key={item.id} className="flex justify-between">
                <span>
                  {item.name} (x{item.quantity})
                </span>
                <span>${(item.price * item.quantity).toFixed(2)}</span>
              </div>
            ))}
          </div>
          <div className="text-xl border-t mt-4 pt-4">
            <div className="flex justify-between font-bold text-3xl">
              <span>{t("cart.total")}</span>
              <span>${total.toFixed(2)}</span>
            </div>
          </div>
        </div>

        <div className="bg-primary text-secondary mt-8 p-6 rounded-lg shadow-md">
          <h2 className="text-2xl font-bold mb-4">{t("cart.paymentInfo")}</h2>
          <label className={styles.label}>{t("cart.name")}</label>
          <input
            className={styles.input}
            type="text"
            value={customerName}
            onChange={(e) => setCustomerName(e.target.value)}
            required
          />
          <label className={styles.label}>{t("cart.email")}</label>
          <input
            className={styles.input}
            type="email"
            value={customerEmail}
            onChange={(e) => setCustomerEmail(e.target.value)}
            required
          />

          <div className="mx-auto mt-8 w-1/2">
          <PayPalButton
            customerName={customerName}
            customerEmail={customerEmail}
            onTransactionComplete={handleTransactionComplete}
          />
          </div>
        </div>
      </div>
    </Layout>
  );
};

export default CheckoutPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  input:
    "bg-semilight placeholder:text-light text-pink text-xl w-full p-2 border rounded",
  label: "block text-lg font-medium mb-1",
};
