import React, { useContext, useEffect } from "react";
import { CartContext } from "../context/cartContext";

declare global {
  interface Window {
    paypal: any;
  }
}
// Definir tipos para los parámetros de PayPal
interface PayPalActions {
  order: {
    create: (data: Record<string, unknown>) => Promise<string>;
    capture: () => Promise<PayPalOrderDetails>;
  };
}
interface PayPalOrderDetails {
  payer: {
    name: {
      given_name: string;
    };
  };
}
interface PayPalButtonProps {
    customerName: string;
    customerEmail: string;
    onTransactionComplete: (orderDetails: string, totalAmount: string, name: string, email: string) => Promise<void>;
  }

const PayPalButton: React.FC<PayPalButtonProps> = ({ customerName, customerEmail, onTransactionComplete }) => {
  const cartContext = useContext(CartContext);
  const { cart } = cartContext || { cart: [] };
  const total = cart.reduce((sum, item) => sum + item.price * item.quantity, 0).toFixed(2);

  useEffect(() => {
    const script = document.createElement("script");
    // script.src = "https://www.paypal.com/sdk/js?client-id=ATSXUxQBYKUNbGCMSV4ldv3sOrYSoTtgmD0VMLmQfSjTcDzvhE-B5D-Ruonc6bbJeXPFRTREROfjnFhd&currency=CAD";
    script.src = "https://www.paypal.com/sdk/js?client-id=AXU-5AjmWPC6v4kng-gJw3qc0Jkjz4KjUvydFAS_1kURgM0QurxRTFMtcot2WyTRGzpo5HD6It0OAwIr&currency=CAD";
    script.async = true;
    script.onload = () => {
      window.paypal.Buttons({
        createOrder: (_data: unknown, actions: PayPalActions) => {
          return actions.order.create({
            purchase_units: [{ amount: { value: total } }]
          });
        },
        onApprove: async (_data: unknown, actions: PayPalActions) => {
        const details = await actions.order.capture();
        const orderDetails = cart.map(item =>
          `${item.name} | Cantidad: ${item.quantity} | Precio: ${(item.price * item.quantity).toFixed(2)} CAD`
        ).join("\n");

        await onTransactionComplete(orderDetails, total, customerName, customerEmail);
        },
        onError: (err: unknown) => console.error("Error en PayPal:", err),
      }).render("#paypal-button-container");
    };
    document.body.appendChild(script);
    return () => {
        document.body.removeChild(script); // Eliminar script anterior al desmontar
      };
    }, [total, customerName, customerEmail]);

  return <div id="paypal-button-container"></div>;
};

export default PayPalButton;
